    rw_cells asegs mm (P + 200) [C8 (Z_to_bv 64 O3); C8 (Z_to_bv 64 O2); C8 (Z_to_bv 64 C3); C8 (Z_to_bv 64 C2)] ->
    rw_cells asegs mm (P + 232) [C8 (Z_to_bv 64 C1)] ->
    rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] ->
    0 <= Q0 -> DST + 8 <= O2 -> O2 + 8 <= O3 -> O3 + 8 <= O4 -> O4 + Q0 + 4 <= DST + dcap ->
    Q0 + 4 <= O2 - DST -> O2 + Q0 + 4 <= O3 -> O3 + Q0 + 4 <= O4 ->
    0 <= B1 <= 64 -> 0 <= B2 <= 64 -> 0 <= B3 <= 64 -> 0 <= B4 <= 64 ->
    0 <= C1 < 2^64 -> 0 <= C2 < 2^64 -> 0 <= C3 < 2^64 -> 0 <= C4 < 2^64 -> 0 <= OL < 2^64 ->
    0 <= N1 <= 12 -> 0 <= N2 <= 12 -> 0 <= N3 <= 12 -> 0 <= N4 <= 12 ->
    0 <= N5 <= 12 -> 0 <= N6 <= 12 -> 0 <= N7 <= 12 -> 0 <= N8 <= 12 ->
    (forall (mm' : amem) (M9 M10 M11 M12 M13 M14 M15 M16 : Z) (z6 z11 z12 z13 z14 z18 z29 z31 : word),
